COMP_MAP = str.maketrans(
    "ACGTURYSWKMBDHVNacgturyswkmbdhvn-",
    "TGCAAYRSWMKVHDBNtgcaayrswmkvhdbn-",
)

AMB2 = {
    "M": ("A", "C"),
    "R": ("A", "G"),
    "W": ("A", "T"),
    "S": ("C", "G"),
    "Y": ("C", "T"),
    "K": ("G", "T"),
}
AMB3 = {"V", "H", "D", "B"}
IUPAC_FROM_SET = {
    frozenset({"A"}): "A",
    frozenset({"C"}): "C",
    frozenset({"G"}): "G",
    frozenset({"T"}): "T",
    frozenset({"A", "C"}): "M",
    frozenset({"A", "G"}): "R",
    frozenset({"A", "T"}): "W",
    frozenset({"C", "G"}): "S",
    frozenset({"C", "T"}): "Y",
    frozenset({"G", "T"}): "K",
    frozenset({"A", "C", "G"}): "V",
    frozenset({"A", "C", "T"}): "H",
    frozenset({"A", "G", "T"}): "D",
    frozenset({"C", "G", "T"}): "B",
    frozenset({"A", "C", "G", "T"}): "N",
}

MASKED_RE = re.compile(r"[^ACGTacgt]+")
PAIR_RE = re.compile(r"^(.*?)([/._-])([12])$")
TEL_PATTERNS = ("TTAGGG", "CCCTAA")
TEL_MIN_LEN = 360


@dataclass
class Record:
    name: str
    comment: str
    seq: str
    qual: Optional[str] = None


@dataclass
class BedEntry:
    name: str
    start: int
    end: int
    strand: Optional[str] = None


class KRand:
    def __init__(self, seed: int = 11) -> None:
        self.x = (seed & ((1 << 64) - 1)) or 11

    def _next_u64(self) -> int:
        x = self.x
        x ^= (x << 7) & ((1 << 64) - 1)
        x ^= x >> 9
        x ^= (x << 8) & ((1 << 64) - 1)
        self.x = x & ((1 << 64) - 1)
        return self.x

    def rand(self) -> float:
        return self._next_u64() / float(1 << 64)

    def randbelow(self, n: int) -> int:
        if n <= 1:
            return 0
        return int(self.rand() * n)

    def randbit(self) -> int:
        return self._next_u64() & 1


def eprint(msg: str, newline: bool = True) -> None:
    end = "\n" if newline else ""
    sys.stderr.write(msg + end)


def is_gzip_path(path: str) -> bool:
    if path.endswith(".gz"):
        return True
    try:
        with open(path, "rb") as fh:
            return fh.read(2) == b"\x1f\x8b"
    except OSError:
        return False


def open_text(path: Optional[str]) -> TextIO:
    if path is None or path == "-":
        return sys.stdin
    if is_gzip_path(path):
        return io.TextIOWrapper(gzip.open(path, "rb"), encoding="ascii", newline="")
    return open(path, "rt", encoding="ascii", newline="")


def split_header(text: str) -> Tuple[str, str]:
    text = text.rstrip("\r\n")
    if not text:
        return "", ""
    parts = text.split(None, 1)
    if len(parts) == 1:
        return parts[0], ""
    return parts[0], parts[1]


def iter_records(path: Optional[str]) -> Iterator[Record]:
    fh = open_text(path)
    close_fh = fh is not sys.stdin
    try:
        first = ""
        while True:
            line = fh.readline()
            if not line:
                return
            line = line.rstrip("\r\n")
            if line == "":
                continue
            first = line
            break
        if first.startswith(">"):
            yield from _iter_fasta_records(fh, first)
        elif first.startswith("@"):
            yield from _iter_fastq_records(fh, first)
    finally:
        if close_fh:
            fh.close()


def _iter_fasta_records(fh: TextIO, first: str) -> Iterator[Record]:
    header = first[1:]
    seq_parts: List[str] = []
    for line in fh:
        line = line.rstrip("\r\n")
        if line.startswith(">"):
            name, comment = split_header(header)
            yield Record(name, comment, "".join(seq_parts), None)
            header = line[1:]
            seq_parts = []
        elif line == "":
            continue
        else:
            seq_parts.append(line)
    name, comment = split_header(header)
    yield Record(name, comment, "".join(seq_parts), None)


def _iter_fastq_records(fh: TextIO, first: str) -> Iterator[Record]:
    header_line = first
    while header_line:
        name, comment = split_header(header_line[1:])
        seq_parts: List[str] = []
        while True:
            line = fh.readline()
            if not line:
                return
            line = line.rstrip("\r\n")
            if line.startswith("+"):
                break
            seq_parts.append(line)
        seq = "".join(seq_parts)
        qual_parts: List[str] = []
        qlen = 0
        while qlen < len(seq):
            line = fh.readline()
            if not line:
                break
            line = line.rstrip("\r\n")
            qual_parts.append(line)
            qlen += len(line)
        qual = "".join(qual_parts)[: len(seq)]
        yield Record(name, comment, seq, qual)
        header_line = ""
        while True:
            line = fh.readline()
            if not line:
                return
            line = line.rstrip("\r\n")
            if line == "":
                continue
            header_line = line
            break
        if not header_line.startswith("@"):
            return


def wrap_text(text: str, width: int) -> List[str]:
    if width <= 0:
        return [text]
    if not text:
        return [""]
    return [text[i : i + width] for i in range(0, len(text), width)]


def write_record(
    rec: Record,
    out: TextIO,
    *,
    as_fasta: Optional[bool] = None,
    line_len: int = 0,
    drop_comment: bool = False,
    name_override: Optional[str] = None,
    comment_override: Optional[str] = None,
) -> None:
    as_fasta = (rec.qual is None) if as_fasta is None else as_fasta
    name = rec.name if name_override is None else name_override
    comment = rec.comment if comment_override is None else comment_override
    if drop_comment:
        comment = ""
    header = name if not comment else f"{name} {comment}"
    if as_fasta:
        out.write(f">{header}\n")
        for part in wrap_text(rec.seq, line_len):
            out.write(part + "\n")
    else:
        qual = rec.qual or ""
        out.write(f"@{header}\n")
        seq_parts = wrap_text(rec.seq, line_len)
        qual_parts = wrap_text(qual, line_len)
        for part in seq_parts:
            out.write(part + "\n")
        out.write("+\n")
        for part in qual_parts:
            out.write(part + "\n")


def revcomp(seq: str) -> str:
    return seq.translate(COMP_MAP)[::-1]


def parse_short_options(
    cmd: str, argv: Sequence[str], spec: Dict[str, bool]
) -> Tuple[Dict[str, List[str]], List[str]]:
    opts: Dict[str, List[str]] = defaultdict(list)
    pos: List[str] = []
    i = 0
    while i < len(argv):
        token = argv[i]
        if token == "--":
            pos.extend(argv[i + 1 :])
            break
        if not token.startswith("-") or token == "-" or token.startswith("--"):
            pos.append(token)
            i += 1
            continue
        j = 1
        while j < len(token):
            ch = token[j]
            if ch not in spec:
                eprint(f"{cmd}: invalid option -- '{ch}'")
                j += 1
                continue
            if not spec[ch]:
                opts[ch].append("1")
                j += 1
                continue
            if j + 1 < len(token):
                val = token[j + 1 :]
                opts[ch].append(val)
                j = len(token)
            elif i + 1 < len(argv):
                i += 1
                opts[ch].append(argv[i])
                j = len(token)
            else:
                eprint(f"{cmd}: option requires an argument -- '{ch}'")
                j = len(token)
        i += 1
    return opts, pos


def load_name_list(path: str) -> set[str]:
    names: set[str] = set()
    fh = open_text(path)
    close_fh = fh is not sys.stdin
    try:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            names.add(line.split()[0])
    finally:
        if close_fh:
            fh.close()
    return names


def parse_region_or_name_list(path: str) -> Tuple[Optional[List[BedEntry]], Optional[set[str]]]:
    fh = open_text(path)
    close_fh = fh is not sys.stdin
    lines: List[str] = []
    try:
        for line in fh:
            line = line.rstrip("\r\n")
            if line:
                lines.append(line)
    finally:
        if close_fh:
            fh.close()
    if not lines:
        return [], set()
    bed_entries: List[BedEntry] = []
    for line in lines:
        fields = line.split("\t")
        if len(fields) < 3:
            return None, {ln.split()[0] for ln in lines}
        try:
            start = int(fields[1])
            end = int(fields[2])
        except ValueError:
            return None, {ln.split()[0] for ln in lines}
        strand = fields[5] if len(fields) >= 6 and fields[5] in {"+", "-"} else None
        bed_entries.append(BedEntry(fields[0], start, end, strand))
    return bed_entries, None


def load_mask_regions(path: str) -> Dict[str, List[Tuple[int, int]]]:
    bed, _ = parse_region_or_name_list(path)
    regions: Dict[str, List[Tuple[int, int]]] = defaultdict(list)
    for entry in bed or []:
        regions[entry.name].append((entry.start, entry.end))
    return regions


def apply_mask_regions(seq: str, regions: Iterable[Tuple[int, int]]) -> str:
    chars = list(seq)
    n = len(chars)
    for start, end in regions:
        s = max(0, start)
        e = min(n, end)
        for i in range(s, e):
            chars[i] = chars[i].lower()
    return "".join(chars)


def qmask(seq: str, qual: str, qcut: int, qoff: int, repl: Optional[str]) -> str:
    chars = list(seq)
    for i, (base, qch) in enumerate(zip(seq, qual)):
        q = ord(qch) - qoff
        if q < qcut:
            chars[i] = repl[0] if repl else base.lower()
    return "".join(chars)


def cmd_seq(argv: Sequence[str]) -> int:
    opts, pos = parse_short_options("seq", argv, {"a": False, "Q": True, "q": True, "n": True, "C": False, "l": True, "r": False, "M": True})
    infile = pos[0] if pos else None
    qoff = int(opts["Q"][-1]) if opts["Q"] else 33
    qcut = int(float(opts["q"][-1])) if opts["q"] else None
    repl = opts["n"][-1] if opts["n"] else None
    drop_comment = bool(opts["C"])
    line_len = int(opts["l"][-1]) if opts["l"] else 0
    do_rev = bool(opts["r"])
    as_fasta_flag = bool(opts["a"])
    mask_regions = load_mask_regions(opts["M"][-1]) if opts["M"] else {}
    for rec in iter_records(infile):
        seq = rec.seq
        qual = rec.qual
        if rec.name in mask_regions:
            seq = apply_mask_regions(seq, mask_regions[rec.name])
        if qual is not None and qcut is not None:
            seq = qmask(seq, qual, qcut, qoff, repl)
        if do_rev:
            seq = revcomp(seq)
            if qual is not None:
                qual = qual[::-1]
        out_rec = Record(rec.name, rec.comment, seq, None if as_fasta_flag else qual)
        write_record(out_rec, sys.stdout, as_fasta=(qual is None or as_fasta_flag), line_len=line_len, drop_comment=drop_comment)
    return 0


def cmd_size(argv: Sequence[str]) -> int:
    infile = argv[0] if argv else None
    n_seq = 0
    n_bases = 0
    for rec in iter_records(infile):
        n_seq += 1
        n_bases += len(rec.seq)
    sys.stdout.write(f"{n_seq}\t{n_bases}\n")
    return 0


def base_set(ch: str) -> frozenset[str]:
    ch = ch.upper()
    if ch in "ACGT":
        return frozenset({ch})
    if ch in AMB2:
        return frozenset(AMB2[ch])
    if ch == "V":
        return frozenset({"A", "C", "G"})
    if ch == "H":
        return frozenset({"A", "C", "T"})
    if ch == "D":
        return frozenset({"A", "G", "T"})
    if ch == "B":
        return frozenset({"C", "G", "T"})
    if ch == "N":
        return frozenset({"A", "C", "G", "T"})
    return frozenset()


def cmd_comp(argv: Sequence[str]) -> int:
    _, pos = parse_short_options("comp", argv, {})
    infile = pos[0] if pos else None
    for rec in iter_records(infile):
        a = c = g = t = amb2 = amb3 = other = tv = ts = 0
        gc = 0
        for ch in rec.seq.upper():
            if ch == "A":
                a += 1
            elif ch == "C":
                c += 1
                gc += 1
            elif ch == "G":
                g += 1
                gc += 1
            elif ch == "T":
                t += 1
            elif ch in AMB2:
                amb2 += 1
                if ch in {"M", "W", "S", "K"}:
                    tv += 1
                else:
                    ts += 1
            elif ch in AMB3:
                amb3 += 1
            else:
                other += 1
        sys.stdout.write(
            f"{rec.name}\t{len(rec.seq)}\t{a}\t{c}\t{g}\t{t}\t{amb2}\t{amb3}\t{other}\t{gc}\t{tv}\t{ts}\t0\n"
        )
    return 0


def parse_fraction_or_number(text: str) -> Tuple[bool, float]:
    if any(ch in text for ch in ".eE"):
        return True, float(text)
    try:
        return False, float(int(text))
    except ValueError:
        return True, float(text)


def reservoir_sample(records: Iterator[Record], k: int, rng: KRand) -> List[Record]:
    reservoir: List[Record] = []
    for idx, rec in enumerate(records):
        if idx < k:
            reservoir.append(rec)
        else:
            j = rng.randbelow(idx + 1)
            if j < k:
                reservoir[j] = rec
    return reservoir


def sample_indices(n: int, k: int, rng: KRand) -> List[int]:
    k = min(k, n)
    pool = list(range(n))
    res: List[int] = []
    for _ in range(k):
        j = rng.randbelow(len(pool))
        res.append(pool.pop(j))
    res.sort()
    return res


def cmd_sample(argv: Sequence[str]) -> int:
    opts, pos = parse_short_options("sample", argv, {"2": False, "s": True})
    if len(pos) < 2:
        sys.stderr.write(USAGE_SAMPLE)
        return 1
    infile = pos[0]
    frac_mode, val = parse_fraction_or_number(pos[1])
    two_pass = bool(opts["2"])
    seed = int(opts["s"][-1]) if opts["s"] else 11
    rng = KRand(seed)
    if frac_mode:
        if two_pass:
            eprint("[W::stk_sample] when sampling a fraction, option -2 is ignored.", newline=False)
        frac = val
        for rec in iter_records(infile):
            if frac > 0 and rng.rand() < frac:
                write_record(rec, sys.stdout, as_fasta=(rec.qual is None))
        return 0
    k = int(val)
    if k <= 0:
        return 0
    if two_pass:
        n = sum(1 for _ in iter_records(infile))
        if k >= n:
            for rec in iter_records(infile):
                write_record(rec, sys.stdout, as_fasta=(rec.qual is None))
            return 0
        keep = set(sample_indices(n, k, rng))
        for idx, rec in enumerate(iter_records(infile)):
            if idx in keep:
                write_record(rec, sys.stdout, as_fasta=(rec.qual is None))
        return 0
    reservoir = reservoir_sample(iter_records(infile), k, rng)
    for rec in reservoir:
        write_record(rec, sys.stdout, as_fasta=(rec.qual is None))
    return 0


def subseq_record(rec: Record, start: int, end: int, strand: Optional[str], line_len: int, tabular: bool, strand_aware: bool) -> None:
    start = max(0, start)
    end = min(len(rec.seq), end)
    seq = rec.seq[start:end]
    qual = rec.qual[start:end] if rec.qual is not None else None
    if strand_aware and strand == "-":
        seq = revcomp(seq)
        if qual is not None:
            qual = qual[::-1]
    if tabular:
        if strand_aware:
            sys.stdout.write(f"{rec.name}\t{start + 1}\t\n{seq}\n")
        else:
            sys.stdout.write(f"{rec.name}\t{start + 1}\t{seq}\n")
        return
    name = f"{rec.name}:{start + 1}-{end}"
    out_rec = Record(name, rec.comment, seq, None if strand_aware else qual)
    write_record(out_rec, sys.stdout, as_fasta=(strand_aware or qual is None), line_len=line_len)


def cmd_subseq(argv: Sequence[str]) -> int:
    opts, pos = parse_short_options("subseq", argv, {"t": False, "s": False, "l": True})
    if len(pos) < 2:
        sys.stderr.write(USAGE_SUBSEQ)
        return 1
    infile, listfile = pos[0], pos[1]
    line_len = int(opts["l"][-1]) if opts["l"] else 0
    tabular = bool(opts["t"])
    strand_aware = bool(opts["s"])
    bed_entries, names = parse_region_or_name_list(listfile)
    if bed_entries is not None:
        rec_map = {rec.name: rec for rec in iter_records(infile)}
        for entry in bed_entries:
            rec = rec_map.get(entry.name)
            if rec is None:
                continue
            subseq_record(rec, entry.start, entry.end, entry.strand, line_len, tabular, strand_aware)
    else:
        keep = names or set()
        for rec in iter_records(infile):
            if rec.name in keep:
                if tabular:
                    sys.stdout.write(f"{rec.name}\t1\t{rec.seq}\n")
                else:
                    write_record(rec, sys.stdout, as_fasta=(strand_aware or rec.qual is None), line_len=line_len)
    return 0


def errq_from_counts(base_counts: Dict[str, float]) -> float:
    total = sum(base_counts.values())
    if total <= 0:
        return 0.0
    best = max(base_counts.values())
    err = max(1e-4, 1.0 - best / total)
    return -10.0 * math.log10(err)


def fmt_pct(x: float) -> str:
    return f"{x:.1f}"


def fmt_pct_q(x: float) -> str:
    return f"{x:.2f}"


def cmd_fqchk(argv: Sequence[str]) -> int:
    opts, pos = parse_short_options("fqchk", argv, {"q": True})
    if len(pos) < 1:
        sys.stderr.write(USAGE_FQCHK)
        return 1
    qcut = int(opts["q"][-1]) if opts["q"] else 20
    recs = list(iter_records(pos[0]))
    if not recs:
        return 0
    lengths = [len(rec.seq) for rec in recs]
    quals = sorted({ord(ch) - 33 for rec in recs for ch in (rec.qual or "")})
    sys.stdout.write(
        f"min_len: {min(lengths)}; max_len: {max(lengths)}; avg_len: {sum(lengths) / len(lengths):.2f}; {len(quals)} distinct quality values\n"
    )
    per_pos: List[Dict[str, float]] = []
    max_len = max(lengths)
    for _ in range(max_len):
        per_pos.append(defaultdict(float))
    all_counts: Dict[str, float] = defaultdict(float)
    all_q = 0.0
    all_n = 0
    qual_bins: Counter[int] = Counter()
    per_pos_bins: List[Counter[int]] = [Counter() for _ in range(max_len)]
    for rec in recs:
        qual = rec.qual or ""
        for i, base in enumerate(rec.seq):
            b = base.upper()
            if b not in "ACGT":
                b = "N"
            q = ord(qual[i]) - 33 if i < len(qual) else 0
            all_counts[b] += 1
            per_pos[i][b] += 1
            all_q += q
            all_n += 1
            qual_bins[q] += 1
            per_pos_bins[i][q] += 1
    if qcut == 0:
        header_cols = [f"%Q{q}" for q in quals]
    else:
        header_cols = ["%low", "%high"]
    sys.stdout.write("POS\t#bases\t%A\t%C\t%G\t%T\t%N\tavgQ\terrQ\t" + "\t".join(header_cols) + "\n")

    def write_row(label: str, counts: Dict[str, float], qcounter: Counter[int], n_bases: int, qsum: float) -> None:
        a = counts.get("A", 0.0)
        c = counts.get("C", 0.0)
        g = counts.get("G", 0.0)
        t = counts.get("T", 0.0)
        n = counts.get("N", 0.0)
        avg_q = qsum / n_bases if n_bases else 0.0
        err_q = errq_from_counts(counts)
        cols = [
            label,
            str(n_bases),
            fmt_pct(100.0 * a / n_bases if n_bases else 0.0),
            fmt_pct(100.0 * c / n_bases if n_bases else 0.0),
            fmt_pct(100.0 * g / n_bases if n_bases else 0.0),
            fmt_pct(100.0 * t / n_bases if n_bases else 0.0),
            fmt_pct(100.0 * n / n_bases if n_bases else 0.0),
            f"{avg_q:.1f}",
            f"{err_q:.1f}",
        ]
        if qcut == 0:
            for q in quals:
                cols.append(fmt_pct_q(100.0 * qcounter.get(q, 0) / n_bases if n_bases else 0.0))
        else:
            low = sum(v for q, v in qcounter.items() if q < qcut)
            high = n_bases - low
            cols.append(fmt_pct(100.0 * low / n_bases if n_bases else 0.0))
            cols.append(fmt_pct(100.0 * high / n_bases if n_bases else 0.0))
        sys.stdout.write("\t".join(cols) + "\n")

    write_row("ALL", all_counts, qual_bins, all_n, all_q)
    for i in range(max_len):
        counts = per_pos[i]
        n_bases = int(sum(counts.values()))
        qsum = sum(q * c for q, c in per_pos_bins[i].items())
        write_row(str(i + 1), counts, per_pos_bins[i], n_bases, float(qsum))
    return 0


