    if len(pos) < 2:
        sys.stderr.write(USAGE_SPLIT)
        return 1
    n_out = int(opts["n"][-1]) if opts["n"] else 10
    line_len = int(opts["l"][-1]) if opts["l"] else 0
    prefix, infile = pos[0], pos[1]
    handles: List[TextIO] = []
    try:
        for i in range(1, n_out + 1):
            handles.append(open(f"{prefix}.{i:05d}.fa", "wt", encoding="ascii", newline=""))
