    return 0


def phred_best_segment(qual: str, cutoff: float, min_len: int) -> Tuple[int, int]:
    n = len(qual)
    if n == 0 or min_len >= n:
        return 0, n
    scores = [cutoff - 10 ** (-(ord(ch) - 33) / 10.0) for ch in qual]
    prefix = [0.0]
    for s in scores:
        prefix.append(prefix[-1] + s)
    best_sum = -1e100
    best = (0, n)
    min_prefix = prefix[0]
    min_pos = 0
    for end in range(min_len, n + 1):
        cand_prefix = prefix[end - min_len]
        if cand_prefix < min_prefix:
            min_prefix = cand_prefix
            min_pos = end - min_len
        cur = prefix[end] - min_prefix
        if cur > best_sum + 1e-12:
            best_sum = cur
            best = (min_pos, end)
    if best_sum <= 0:
        return 0, n
    return best


def cmd_trimfq(argv: Sequence[str]) -> int:
    opts, pos = parse_short_options("trimfq", argv, {"q": True, "l": True, "b": True, "e": True, "L": True})
    # Match the observed parser quirk for -Q.
    if any(arg == "-Q" or arg.startswith("-Q") for arg in argv):
        eprint("trimfq: invalid option -- 'Q'")
    infile = pos[0] if pos else None
    cutoff = float(opts["q"][-1]) if opts["q"] else 0.05
    min_len = int(opts["l"][-1]) if opts["l"] else 30
    trim_left = int(opts["b"][-1]) if opts["b"] else 0
    trim_right = int(opts["e"][-1]) if opts["e"] else 0
    retain_left = int(opts["L"][-1]) if opts["L"] else 0
    for rec in iter_records(infile):
        seq = rec.seq
        qual = rec.qual
        start, end = 0, len(seq)
        if trim_left or trim_right:
            start = min(trim_left, len(seq))
            end = max(start, len(seq) - trim_right)
        elif retain_left:
            end = min(end, retain_left)
        elif qual is not None:
            start, end = phred_best_segment(qual, cutoff, min_len)
        seq = seq[start:end]
        qual = qual[start:end] if qual is not None else None
        write_record(Record(rec.name, rec.comment, seq, qual), sys.stdout, as_fasta=(qual is None))
    return 0


def pair_key(name: str) -> Tuple[str, Optional[str]]:
    m = PAIR_RE.match(name)
    if not m:
        return name, None
    return m.group(1), m.group(3)


def are_pair(a: str, b: str) -> bool:
    ra, ma = pair_key(a)
    rb, mb = pair_key(b)
    if ma and mb:
        return ra == rb and {ma, mb} == {"1", "2"}
    return ra == rb == a == b


def cmd_dropse(argv: Sequence[str]) -> int:
    infile = argv[0] if argv else None
    prev: Optional[Record] = None
    for rec in iter_records(infile):
        if prev is None:
            prev = rec
            continue
        if are_pair(prev.name, rec.name):
            write_record(prev, sys.stdout, as_fasta=(prev.qual is None))
            write_record(rec, sys.stdout, as_fasta=(rec.qual is None))
            prev = None
        else:
            prev = rec
    return 0


