        out_rec = Record(str(i), last_comment, rec.seq, rec.qual)
        write_record(out_rec, sys.stdout, as_fasta=(rec.qual is None))
    return 0


def hpc_seq(seq: str) -> str:
    if not seq:
        return seq
    out = [seq[0]]
    for ch in seq[1:]:
        if ch != out[-1]:
            out.append(ch)
    return "".join(out)


