        write_record(out, sys.stdout, as_fasta=True, drop_comment=True)
    return 0


def find_gaps(seq: str, min_len: int) -> List[Tuple[int, int]]:
    return [(m.start(), m.end()) for m in MASKED_RE.finditer(seq) if m.end() - m.start() >= min_len]


