def cmd_cutn(argv: Sequence[str]) -> int:
    opts, pos = parse_short_options("cutN", argv, {"n": True, "p": True, "g": False})
    if len(pos) < 1:
        sys.stderr.write(USAGE_CUTN)
        return 1
    min_len = int(opts["n"][-1]) if opts["n"] else 1000
    gaps_only = bool(opts["g"])
    for rec in iter_records(pos[0]):
        gaps = find_gaps(rec.seq, min_len)
        if gaps_only:
            for start, end in gaps:
                sys.stdout.write(f"{rec.name}\t{start}\t{end}\n")
            continue
        last = 0
        for start, end in gaps + [(len(rec.seq), len(rec.seq))]:
            if start > last:
                seg = rec.seq[last:start]
                name = f"{rec.name}:{last + 1}-{start}"
                write_record(Record(name, "", seg, None), sys.stdout, as_fasta=True, drop_comment=True)
            last = end
    return 0


