def cmd_mutfa(argv: Sequence[str]) -> int:
    if len(argv) < 2:
        sys.stderr.write(USAGE_MUTFA)
        return 1
    mut: Dict[str, Dict[int, str]] = defaultdict(dict)
    with open_text(argv[1]) as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            fields = line.split()
            if len(fields) < 4:
                continue
            try:
                pos = int(fields[1]) - 1
            except ValueError:
                continue
            mut[fields[0]][pos] = fields[3][0]
    for rec in iter_records(argv[0]):
        seq = list(rec.seq)
        for pos, base in mut.get(rec.name, {}).items():
            if 0 <= pos < len(seq):
                seq[pos] = base
        write_record(Record(rec.name, "", "".join(seq), None), sys.stdout, as_fasta=True, drop_comment=True)
    return 0


def cmd_famask(argv: Sequence[str]) -> int:
    if len(argv) < 2:
        sys.stderr.write(USAGE_FAMASK)
        return 1
    src_recs = list(iter_records(argv[0]))
    mask_recs = list(iter_records(argv[1]))
    last_mask = mask_recs[-1] if mask_recs else Record("", "", "", None)
    for i, src in enumerate(src_recs):
        mask = mask_recs[i] if i < len(mask_recs) else Record(last_mask.name, last_mask.comment, "", None)
        if src.name != mask.name:
            eprint(f"[stk_famask] Different sequence names: {src.name} != {mask.name}")
        if len(src.seq) != len(mask.seq):
            eprint(f"[stk_famask] Unequal sequence length: {len(src.seq)} != {len(mask.seq)}")
        out = []
        for a, b in zip(src.seq, mask.seq):
            out.append(a.lower() if b.islower() else a)
        write_record(Record(src.name, "", "".join(out), None), sys.stdout, as_fasta=True, drop_comment=True)
    return 0


def sanitize_input_base(ch: str, q: Optional[str], qcut: int, suppress_hets: bool, randomize_hets: bool, rng: KRand) -> str:
    if q is not None and qcut > 0 and ord(q) - 33 < qcut:
        return "N"
    u = ch.upper()
    if suppress_hets and u in AMB2:
        return "N"
    if randomize_hets and u in AMB2:
        return choose_randbase(ch, rng)
    return ch


def mergefa_base(
    a: str,
    b: str,
    *,
    intersection: bool,
    lowercase_n: bool,
    randomize: bool,
    suppress_hets: bool,
    rng: KRand,
) -> Tuple[str, Tuple[int, int, int, int, int]]:
    stats = [0, 0, 0, 0, 0]
    sa = base_set(a)
    sb = base_set(b)
    ua = a.upper()
    ub = b.upper()
    definite_a = ua in "ACGT"
    definite_b = ub in "ACGT"
    if definite_a and definite_b:
        if ua == ub:
            stats[0] += 1
            return a if a == b else ua, tuple(stats)
        stats[1] += 1
        return ("x" if intersection else IUPAC_FROM_SET.get(frozenset({ua, ub}), "N")), tuple(stats)
    if definite_a and ub == "N":
        if intersection:
            return (a.lower() if lowercase_n else a), tuple(stats)
        if suppress_hets:
            return "n", tuple(stats)
        if randomize:
            return a.lower(), tuple(stats)
        return ("n" if lowercase_n else "N"), tuple(stats)
    if ua == "N" and definite_b:
        if intersection:
            return (b.lower() if lowercase_n else b), tuple(stats)
        if suppress_hets:
            return "n", tuple(stats)
        if randomize:
            return "n", tuple(stats)
        return ("n" if lowercase_n else "N"), tuple(stats)
    if ua in AMB2 and definite_b:
        stats[2] += 1
    elif definite_a and ub in AMB2:
        stats[3] += 1
    elif ua in AMB2 or ub in AMB2:
        stats[4] += 1
    if intersection:
        inter = sa & sb
        if not inter:
            return "x", tuple(stats)
        base = IUPAC_FROM_SET.get(frozenset(inter), "N")
        if lowercase_n and ("N" in {ua, ub}):
            base = base.lower()
        return base, tuple(stats)
    union = sa | sb
    if not union:
        return "N", tuple(stats)
    base = IUPAC_FROM_SET.get(frozenset(union), "N")
    if suppress_hets and base not in "ACGT":
        base = "n"
    return base, tuple(stats)


def cmd_mergefa(argv: Sequence[str]) -> int:
    opts, pos = parse_short_options("mergefa", argv, {"q": True, "i": False, "m": False, "r": False, "h": False})
    if len(pos) < 2:
        sys.stderr.write(USAGE_MERGEFA)
        return 1
    qcut = int(opts["q"][-1]) if opts["q"] else 0
    intersection = bool(opts["i"])
    lowercase_n = bool(opts["m"])
    randomize = bool(opts["r"])
    suppress_hets = bool(opts["h"])
    rng = KRand(11)
    recs1 = list(iter_records(pos[0]))
    recs2 = list(iter_records(pos[1]))
    total = [0, 0, 0, 0, 0]
    for r1, r2 in zip(recs1, recs2):
        seq = []
        q1 = r1.qual or ""
        q2 = r2.qual or ""
        n = min(len(r1.seq), len(r2.seq))
        for i in range(n):
            a = sanitize_input_base(r1.seq[i], q1[i] if i < len(q1) else None, qcut, suppress_hets, randomize, rng)
            b = sanitize_input_base(r2.seq[i], q2[i] if i < len(q2) else None, qcut, suppress_hets, randomize, rng)
            merged, stats = mergefa_base(
                a,
                b,
                intersection=intersection,
                lowercase_n=lowercase_n,
                randomize=randomize,
                suppress_hets=suppress_hets,
                rng=rng,
            )
            seq.append(merged)
            for j in range(5):
                total[j] += stats[j]
        write_record(Record(r1.name, "", "".join(seq), None), sys.stdout, as_fasta=True, drop_comment=True)
    eprint(
        "[stk_mergefa] (same,diff,hom-het,het-hom,het-het)=("
        + ",".join(str(x) for x in total)
        + ")"
    )
    return 0


def cmd_hety(argv: Sequence[str]) -> int:
    opts, pos = parse_short_options("hety", argv, {"w": True, "t": True, "m": False})
    if len(pos) < 1:
        sys.stderr.write(USAGE_HETY)
        return 1
    mask_lower = bool(opts["m"])
    for rec in iter_records(pos[0]):
        seq = rec.seq
        considered = 0
        hets = 0
        for ch in seq:
            if mask_lower and ch.islower():
                continue
            u = ch.upper()
            if u in "ACGT":
                considered += 1
            elif u in AMB2:
                considered += 1
                hets += 1
        rate = 50000.0 * hets / considered if considered else 0.0
        sys.stdout.write(f"{rec.name}\t0\t{len(seq)}\t{rate:.2f}\t{considered}\t{hets}\n")
    return 0


def local_target_regions(seq: str, target: set[str], frac: float, min_len: int, xdrop: float) -> List[Tuple[int, int, int]]:
    neg = frac / max(1e-9, 1.0 - frac)
    regions: List[Tuple[int, int, int]] = []
    cur_score = 0.0
    cur_start = 0
    best_score = 0.0
    best_end = 0
    for i, ch in enumerate(seq.upper()):
        score = 1.0 if ch in target else -neg
        if cur_score <= 0:
            cur_score = score
            cur_start = i
            best_score = max(score, 0.0)
            best_end = i + 1
        else:
            cur_score += score
            if cur_score > best_score:
                best_score = cur_score
                best_end = i + 1
        if cur_score <= 0:
            if best_score >= xdrop and best_end - cur_start >= min_len:
                regions.append((cur_start, best_end, int(best_end - cur_start)))
            cur_score = 0.0
    if cur_score > 0 and best_score >= xdrop and best_end - cur_start >= min_len:
        regions.append((cur_start, best_end, int(best_end - cur_start)))
    return regions


def cmd_gc(argv: Sequence[str]) -> int:
    opts, pos = parse_short_options("gc", argv, {"w": False, "f": True, "l": True, "x": True})
    if len(pos) < 1:
        sys.stderr.write(USAGE_GC)
        return 1
    at_mode = bool(opts["w"])
    frac = float(opts["f"][-1]) if opts["f"] else 0.60
    min_len = int(opts["l"][-1]) if opts["l"] else 20
    xdrop = float(opts["x"][-1]) if opts["x"] else 10.0
    target = {"A", "T"} if at_mode else {"G", "C"}
    for rec in iter_records(pos[0]):
        for start, end, score in local_target_regions(rec.seq, target, frac, min_len, xdrop):
            sys.stdout.write(f"{rec.name}\t{start}\t{end}\t{score}\n")
    return 0


def find_telomeres(seq: str) -> List[Tuple[int, int]]:
    seq_u = seq.upper()
    out: List[Tuple[int, int]] = []
    i = 0
    n = len(seq_u)
    while i < n:
        best_end = i
        for motif in TEL_PATTERNS:
            j = i
            while seq_u.startswith(motif, j):
                j += len(motif)
            if j - i > best_end - i:
                best_end = j
        if best_end - i >= TEL_MIN_LEN:
            out.append((i, best_end))
            i = best_end
        else:
            i += 1
    return out


def cmd_telo(argv: Sequence[str]) -> int:
    _, pos = parse_short_options("telo", argv, {})
    infile = pos[0] if pos else None
    total_tel = 0
    total_bases = 0
    for rec in iter_records(infile):
        total_bases += len(rec.seq)
        telos = find_telomeres(rec.seq)
        for start, end in telos:
            total_tel += end - start
            sys.stdout.write(f"{rec.name}\t{start}\t{end}\t{end - start}\n")
    sys.stderr.write(f"{total_tel}\t{total_bases}\n")
    return 0


def dispatch(argv: Sequence[str]) -> int:
    if len(argv) < 2:
        sys.stdout.write(TOP_LEVEL_USAGE)
        return 1
    cmd = argv[1]
    args = list(argv[2:])
    table = {
        "seq": cmd_seq,
        "size": cmd_size,
        "comp": cmd_comp,
        "sample": cmd_sample,
        "subseq": cmd_subseq,
        "fqchk": cmd_fqchk,
        "mergepe": cmd_mergepe,
        "split": cmd_split,
        "trimfq": cmd_trimfq,
        "hety": cmd_hety,
        "gc": cmd_gc,
        "mutfa": cmd_mutfa,
        "mergefa": cmd_mergefa,
        "famask": cmd_famask,
        "dropse": cmd_dropse,
        "rename": cmd_rename,
        "randbase": cmd_randbase,
        "cutN": cmd_cutn,
        "gap": cmd_gap,
        "listhet": cmd_listhet,
        "hpc": cmd_hpc,
        "telo": cmd_telo,
    }
    fn = table.get(cmd)
    if fn is None:
        eprint(f"[main] unrecognized command '{cmd}'. Abort!")
        return 1
    return fn(args)


def main() -> int:
    try:
        return dispatch(sys.argv)
    except BrokenPipeError:
        return 0


if __name__ == "__main__":
    raise SystemExit(main())

