using namespace std;

double dr(mt19937_64 &g){ return (double)g()/18446744073709551616.0; }

vector<int> alg_reservoir(int n,int k,int seed){ mt19937_64 g(seed); vector<int> r; for(int i=1;i<=n;i++){ if((int)r.size()<k) r.push_back(i); else { long j=(long)(dr(g)*i); if(j<k) r[j]=i; } } return r; }
vector<int> alg_shuffle_prefix(int n,int k,int seed){ mt19937_64 g(seed); vector<int> a(n); iota(a.begin(),a.end(),1); for(int i=0;i<k;i++){ long j=i + (long)(dr(g)*(n-i)); swap(a[i],a[j]); } a.resize(k); return a; }
vector<int> alg_floyd(int n,int k,int seed){ mt19937_64 g(seed); set<int> s; for(int j=n-k+1;j<=n;j++){ int t=1 + (long)(dr(g)*j); if(!s.insert(t).second) s.insert(j); } return vector<int>(s.begin(),s.end()); }
vector<int> alg_smallest(int n,int k,int seed){ mt19937_64 g(seed); vector<pair<double,int>> v; for(int i=1;i<=n;i++) v.push_back({dr(g),i}); nth_element(v.begin(),v.begin()+k,v.end()); v.resize(k); vector<int> r; for(auto &p:v) r.push_back(p.second); sort(r.begin(),r.end()); return r; }
vector<int> alg_choose_skip(int n,int k,int seed){ mt19937_64 g(seed); vector<int> r; int need=k; for(int i=1;i<=n;i++){ if((n-i+1)==need || dr(g) < (double)need/(n-i+1)){ r.push_back(i); --need; if(!need) break; } } return r; }
int main(){
