#include <bits/stdc++.h>
using namespace std;

struct Obs { int seed; vector<int> want; };
vector<Obs> obs={{1,{3,5,8}},{2,{3,7,9}},{3,{1,6,10}},{11,{4,5,6}}};

template<class G> double dr(G &g){ return (double)g() / (double(G::max()) + 1.0); }

template<class G> vector<int> reservoir_d(int n,int k,int seed){ G g(seed); vector<int> r; for(int i=1;i<=n;i++){ if((int)r.size()<k) r.push_back(i); else { long j=(long)(dr(g)*i); if(j<k) r[j]=i; } } sort(r.begin(),r.end()); return r; }

template<class G> vector<int> reservoir_m(int n,int k,int seed){ G g(seed); vector<int> r; for(int i=1;i<=n;i++){ if((int)r.size()<k) r.push_back(i); else { auto j=g()%i; if(j<k) r[j]=i; } } sort(r.begin(),r.end()); return r; }

template<class G> vector<int> skip_d(int n,int k,int seed){ G g(seed); vector<int> r; int need=k; for(int i=1;i<=n;i++){ if(n-i+1==need || dr(g) < (double)need/(n-i+1)){ r.push_back(i); if(--need==0) break; } } return r; }

template<class G> vector<int> skip_m(int n,int k,int seed){ G g(seed); vector<int> r; int need=k; for(int i=1;i<=n;i++){ if(n-i+1==need || (g()%(n-i+1)) < (unsigned)need){ r.push_back(i); if(--need==0) break; } } return r; }

template<class G> vector<int> floyd_d(int n,int k,int seed){ G g(seed); set<int> s; for(int j=n-k+1;j<=n;j++){ int t=1 + (long)(dr(g)*j); if(!s.insert(t).second) s.insert(j); } return vector<int>(s.begin(),s.end()); }

template<class G> vector<int> floyd_m(int n,int k,int seed){ G g(seed); set<int> s; for(int j=n-k+1;j<=n;j++){ int t=1 + (g()%j); if(!s.insert(t).second) s.insert(j); } return vector<int>(s.begin(),s.end()); }

template<class G> vector<int> pop_d(int n,int k,int seed){ G g(seed); vector<int>a(n); iota(a.begin(),a.end(),1); vector<int>r; for(int i=0;i<k;i++){ auto j=(long)(dr(g)*a.size()); r.push_back(a[j]); a.erase(a.begin()+j);} sort(r.begin(),r.end()); return r; }

template<class G> vector<int> pop_m(int n,int k,int seed){ G g(seed); vector<int>a(n); iota(a.begin(),a.end(),1); vector<int>r; for(int i=0;i<k;i++){ auto j=g()%a.size(); r.push_back(a[j]); a.erase(a.begin()+j);} sort(r.begin(),r.end()); return r; }

template<class G> vector<int> shuffle_a(int n,int k,int seed){ G g(seed); vector<int>a(n); iota(a.begin(),a.end(),1); shuffle(a.begin(),a.end(),g); a.resize(k); sort(a.begin(),a.end()); return a; }

template<class G> vector<int> sample_std(int n,int k,int seed){ G g(seed); vector<int>a(n),out; iota(a.begin(),a.end(),1); sample(a.begin(),a.end(),back_inserter(out),k,g); sort(out.begin(),out.end()); return out; }

template<class G> int score(function<vector<int>(int,int,int)> f){ int bad=0; for(auto &o: obs){ auto got=f(10,3,o.seed); if(got!=o.want) bad++; } return bad; }

#define TEST_ENGINE(E) do { \
  cout << #E << " reservoir_d " << score<E>(reservoir_d<E>) << "\n"; \
  cout << #E << " reservoir_m " << score<E>(reservoir_m<E>) << "\n"; \
  cout << #E << " skip_d " << score<E>(skip_d<E>) << "\n"; \
  cout << #E << " skip_m " << score<E>(skip_m<E>) << "\n"; \
  cout << #E << " floyd_d " << score<E>(floyd_d<E>) << "\n"; \
  cout << #E << " floyd_m " << score<E>(floyd_m<E>) << "\n"; \
  cout << #E << " pop_d " << score<E>(pop_d<E>) << "\n"; \
  cout << #E << " pop_m " << score<E>(pop_m<E>) << "\n"; \
  cout << #E << " shuffle_a " << score<E>(shuffle_a<E>) << "\n"; \
  cout << #E << " sample_std " << score<E>(sample_std<E>) << "\n"; \
} while(0)

int main(){
  TEST_ENGINE(mt19937_64);
  TEST_ENGINE(mt19937);
  TEST_ENGINE(minstd_rand0);
  TEST_ENGINE(minstd_rand);
  TEST_ENGINE(ranlux24_base);
  TEST_ENGINE(ranlux48_base);
  TEST_ENGINE(knuth_b);
}
